//! MCP server, served over stdio.

use rmcp::{
    ServerHandler,
    handler::server::tool::ToolRouter,
    model::{Implementation, ServerCapabilities, ServerConfig},
    tool, tool_handler, tool_router,
};
use serde::Serialize;

/// Streamable HTTP transport, mounted by the server.
pub(crate) mod http;

/// What every tool returns: the todo(s) as JSON, or the error for the model.
type Answer = Result<String, String>;

/// MCP server: each `#[tool]` method below is a tool clients can call.
#[derive(Debug, Clone)]
pub(crate) struct Server {
    /// Generated by `#[tool_router]`.
    tool_router: ToolRouter<Self>,
}

#[tool_router]
impl Server {
    /// Tools over `state`.
    fn new() -> Self {
        Self {
            tool_router: Self::tool_router(),
        }
    }

    /// Lists notes.
    #[tool(
        description = "List the vault's notes, as paths like `travel/japan.md`. Each note is usually one subject.",
        annotations(read_only_hint = true)
    )]
    async fn list_notes(&self) -> Answer {
        // list all notes
    }

    /// Add note.
    #[tool(description = "Add a note (created if missing).")]
    async fn add_note(&self) -> Answer {
        // add a note
    }

    /// Update note.
    #[tool(
        description = "Change a note in the vault.",
        annotations(idempotent_hint = true)
    )]
    async fn update_note(&self) -> Answer {
        // update a note
    }

    /// Delete note.
    #[tool(
        description = "Delete a note in the vault.",
        annotations(destructive_hint = true)
    )]
    async fn delete_note(&self) -> Answer {
        // delete a note
    }
}

#[allow(clippy::unused_async_trait_impl)]
#[tool_handler]
impl ServerHandler for Server {
    fn get_info(&self) -> ServerConfig {
        ServerConfig::new(ServerCapabilities::builder().enable_tools().build())
            .with_server_info(Implementation::new(
                env!("CARGO_PKG_NAME"),
                env!("CARGO_PKG_VERSION"),
            ))
            .with_instructions(env!("CARGO_PKG_DESCRIPTION"))
    }
}

/// Pretty JSON, so the model reads it easily.
fn json<T: Serialize>(value: &T) -> Answer {
    serde_json::to_string_pretty(value).map_err(|e| e.to_string())
}

/// The route's error message as the tool's error text.
#[allow(clippy::needless_pass_by_value)] // used as `map_err(err)`
fn err(error: ApiError) -> String {
    error.message().to_owned()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn echo_sends_the_text_back() {
        let args = EchoArgs {
            text: String::from("hello"),
        };
        assert_eq!(Server.echo(Parameters(args)), "hello");
    }

    #[test]
    fn info_advertises_tools() {
        let info = Server.get_info();
        assert!(info.capabilities.tools.is_some());
        assert_eq!(info.server_info.name, env!("CARGO_PKG_NAME"));
    }
}
